package com.example.reports;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

public class ReportStore {
    private final Path root;

    public ReportStore(Path root) {
        this.root = root;
    }

    /** Return the saved report with the given file name. */
    public String readReport(String name) throws IOException {
        Path report = root.resolve(name);
        return new String(Files.readAllBytes(report), StandardCharsets.UTF_8);
    }
}

package com.example.reports;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ReportStoreTest {
    @Test
    void readsSavedReport(@TempDir Path dir) throws Exception {
        Files.write(dir.resolve("q1.txt"), "totals".getBytes(StandardCharsets.UTF_8));
        assertEquals("totals", new ReportStore(dir).readReport("q1.txt"));
    }
}
